4	Mat4 Transform::local_to_parent() const {
5		return Mat4::translate(translation) * rotation.to_mat() * Mat4::scale(scale);
6	}
7	
8	Mat4 Transform::parent_to_local() const {
9		return Mat4::scale(1.0f / scale) * rotation.inverse().to_mat() * Mat4::translate(-translation);
10	}
