331	inline Mat4 Mat4::transpose(const Mat4& m) {
332		Mat4 r;
333		for (uint32_t i = 0; i < 4; i++) {
334			for (uint32_t j = 0; j < 4; j++) {
335				r[i][j] = m[j][i];
336			}
337		}
338		return r;
339	}
340	
341	inline Mat4 Mat4::inverse(const Mat4& m) {
