411	inline Mat4 Mat4::rotate_z_to(Vec3 dir) {
412		Mat4 y = rotate_to(dir);
413		Vec4 _y = y[1];
414		Vec4 _z = y[2];
415		y[1] = _z;
416		y[2] = -_y;
417		return y;
418	}
