469	inline Mat4 Mat4::ortho(float l, float r, float b, float t, float n, float f) {
470		Mat4 rs;
471		rs[0][0] = 2.0f / (r - l);
472		rs[1][1] = 2.0f / (t - b);
473		rs[2][2] = 2.0f / (n - f);
474		rs[3][0] = (-l - r) / (r - l);
475		rs[3][1] = (-b - t) / (t - b);
476		rs[3][2] = -n / (f - n);
477		return rs;
478	}
