480	inline Mat4 Mat4::perspective(float fov, float ar, float n) {
481		float f = 1.0f / std::tan(Radians(fov) / 2.0f);
482		return Mat4( //note: column-major!
483			f / ar, 0.0f, 0.0f,   0.0f,
484			0.0f,   f,    0.0f,   0.0f,
485			0.0f,   0.0f,-1.0f,  -1.0f,
486			0.0f,   0.0f,-2.0f*n, 0.0f
487		);
488	}
