490	inline Mat4 Mat4::look_at(Vec3 pos, Vec3 at, Vec3 up) {
491		Mat4 r = Mat4::Zero;
492		Vec3 F = (at - pos).unit();
493		Vec3 S = cross(F, up).unit();
494		Vec3 U = cross(S, F).unit();
495		r[0][0] = S.x;
496		r[0][1] = U.x;
497		r[0][2] = -F.x;
498		r[1][0] = S.y;
499		r[1][1] = U.y;
500		r[1][2] = -F.y;
501		r[2][0] = S.z;
502		r[2][1] = U.z;
503		r[2][2] = -F.z;
504		r[3][0] = -dot(S, pos);
505		r[3][1] = -dot(U, pos);
506		r[3][2] = dot(F, pos);
507		r[3][3] = 1.0f;
508		return r;
509	}
